    [Theory]
    [MemberData(nameof(Posts))]
    public void Parse_HandlesOctoberProductionPosts(long id, string title, string body, string? failureCode)
    {
        var post = new Post { Id = id, Title = title, Description = body };
        var result = new AnnouncementPreParser(PostFormatter.Moscow).Parse(
            post, new DateTime(2026, 10, 16, 0, 0, 0, DateTimeKind.Utc));

        Assert.Equal(failureCode, result.FailureCode);
        Assert.Equal(failureCode is null, result.Success);
        if (failureCode == "cost_ambiguous")
        {
            Assert.Null(result.Cost);
            Assert.False(result.CanCallApi);
            Assert.NotNull(result.LocalDateTime);
            Assert.NotNull(result.Place);
        }
        if (id == 3416859) Assert.Equal("Соус", result.Place);
        if (id == 3418371) Assert.Null(result.LocalDateTime);
        if (id == 3418779) Assert.Equal(new DateTime(2026, 11, 29, 13, 0, 0), result.LocalDateTime);
        if (id == 3416539) Assert.Equal(new DateTime(2026, 11, 1, 12, 0, 0), result.LocalDateTime);
    }

